[CmdletBinding()]param([Parameter(Mandatory=$true)][string]$Path)
$ErrorActionPreference='Stop';$d=[IO.Path]::GetFullPath($Path);$x=Get-Content (Join-Path $d 'project-story.json') -Raw|ConvertFrom-Json;$all=@();$all+=$x.offer.id;$all+=@($x.pages|% id);$all+=@($x.tickets|% id);$all+=@($x.evidence|% id);$all+=@($x.timeline|% id);if(@($all|Sort-Object -Unique).Count -ne $all.Count){throw 'STORY_DUPLICATE_ID'};if($x.offer.actual_hours -gt $x.offer.planned_hours -or $x.offer.actual_cost -gt $x.offer.planned_cost){throw 'STORY_BUDGET_MISMATCH'};foreach($p in @($x.pages)){if([string]$p.sourcePath -match '^[A-Za-z]:|\.\.|\\' -or -not(Test-Path (Join-Path $d $p.sourcePath) -PathType Leaf)){throw 'STORY_PAGE_SOURCE_INVALID'};if((Get-Content (Join-Path $d $p.sourcePath) -Raw).Trim().Length -eq 0){throw 'STORY_PAGE_EMPTY'};if($p.parent -and @($x.pages|? id -eq $p.parent).Count -ne 1){throw 'STORY_PAGE_PARENT_INVALID'}};foreach($t in @($x.tickets)){if([string]$t.reporter -eq '' -or [string]$t.assignee -eq '' -or [string]$t.priority -notin @('P1','P2','P3','P4') -or @($t.acceptance).Count -eq 0 -or @($t.evidence).Count -eq 0){throw 'STORY_TICKET_FIELDS_INVALID'};if([string]$t.status_history[-1].status -in @('done','closed') -and (@($t.comments|? type -eq 'closing').Count -ne 1 -or @($t.comments|? type -eq 'working').Count -lt 1)){throw 'STORY_TICKET_CLOSURE_INVALID'};if(@($t.worklogs|? hours -le 0).Count -gt 0 -or (@($t.worklogs|Measure-Object hours -Sum).Sum -ne $x.offer.actual_hours)){throw 'STORY_WORKLOG_TOTAL_INVALID'};foreach($c in @($t.comments)){if([string]$c.id -eq '' -or [string]$c.author_role -eq '' -or $c.type -notin @('working','handoff','closing') -or [datetime]$c.time -lt [datetime]$t.created){throw 'STORY_COMMENT_INVALID'}}};for($i=1;$i -lt @($x.timeline).Count;$i++){if([datetime]$x.timeline[$i].time -lt [datetime]$x.timeline[$i-1].time){throw 'STORY_TIMELINE_ORDER_INVALID'}};foreach($e in @($x.timeline)){if([string]$e.role -eq '' -or [string]$e.action -eq '' -or [string]$e.result -eq '' -or [string]$e.nextStep -eq '' -or @($e.evidence).Count -eq 0){throw 'STORY_TIMELINE_FIELDS_INVALID'}};foreach($h in @($x.hypercare)){if([string]$h.daily_page -eq '' -or @($h.tickets).Count -eq 0 -or [string]$h.diagnosis -eq '' -or [string]$h.fix -eq '' -or [string]$h.retest -eq '' -or [string]$h.go_no_go -notin @('GO','NO-GO')){throw 'STORY_HYPERCARE_FIELDS_INVALID'}};if(@($x.hypercare|? status -ne 'closed').Count -gt 0){throw 'STORY_HYPERCARE_INCOMPLETE'};foreach($e in @($x.graph)){if(@($all|? {$_ -eq $e.from}).Count -ne 1 -or @($all|? {$_ -eq $e.to}).Count -ne 1){throw 'STORY_GRAPH_REFERENCE_INVALID'}};Write-Host 'PASS: Hardened project story validates schema, tickets, worklogs, pages, timeline, hypercare and graph.'
